logger.message:
#[%dw 2.0
output application/json skipNullOn="everywhere"
---
{
    "log-message":{
        "message":"start of fetch records sub flow",
        "log-tracepoint": "BEFORE_REQUEST",
        "Log-Level":"INFO",
        "Environment": p('mule.env'),
        "correlationId": correlationId,
        "Payload": null
    }
}]

#[%dw 2.0
output application/json skipNullOn="everywhere"
---
{
    "log-message":{
        "message":"start of fetch records sub flow",
        "log-tracepoint": "BEFORE_REQUEST",
        "Log-Level":"DEBUG",
        "Environment": p('mule.env'),
        "correlationId": correlationId,
        "Payload": write(payload,"application/json")        
    }
}]

